    m = len(age)
    stock = [0.0] * m
    for i in range(m):
        stock[i] = max(0.0, float(age[i]))

    for t in range(L):
        for group in range(2):
            if group == 0:
                g = f
            else:
                g = 1.0 - f

            total = 0.0
            for i in range(m):
                total = total + stock[i]

            sale = 0.0
            if g > 0.0 and total > 0.0:
                M = g * mu
                V = g * (mu * cv) * (mu * cv)
                shape = V / (M * M) - 1.0 / M
                root = max(0.0, shape * shape - 1.0) ** 0.5
                b = 1.0 + shape + root
                c = 1.0 + shape - root
                p1 = 2.0 / (2.0 + M * b)
                p2 = 2.0 / (2.0 + M * c)
                r1 = 1.0 - p1
                r2 = 1.0 - p2
                n = int(total)
                frac = total - n
                e1 = r1 * (1.0 - r1 ** n) / p1 + frac * r1 ** (n + 1)
                e2 = r2 * (1.0 - r2 ** n) / p2 + frac * r2 ** (n + 1)
                expected = e1 / b + e2 / c
                sale = min(total, SALE * expected)

            remaining = sale
